import java.util.ArrayDeque;
import java.util.Queue;

public class TelemetryBuffer {
    private final Queue<String> buffer = new ArrayDeque<>();
    private final int maxCapacity;

    public TelemetryBuffer(int maxCapacity) {
        this.maxCapacity = maxCapacity;
    }

    public boolean enqueuePacket(String packet) {
        if (packet == null) return false;
        if (buffer.size() >= maxCapacity) {
            // Buffer overflow: reject gracefully
            return false;
        }
        return buffer.offer(packet);
    }

    public String consumeNextPacket() {
        return buffer.poll(); // Returns null if empty
    }

    public static void main(String[] args) {
        TelemetryBuffer telemetry = new TelemetryBuffer(2);

        System.out.println("Enqueue pkt1: " + telemetry.enqueuePacket("PKT_A")); // true
        System.out.println("Enqueue pkt2: " + telemetry.enqueuePacket("PKT_B")); // true
        System.out.println("Enqueue pkt3: " + telemetry.enqueuePacket("PKT_C")); // false (Capacity reached!)

        System.out.println("Consumed:     " + telemetry.consumeNextPacket());     // PKT_A (FIFO!)
        System.out.println("Consumed:     " + telemetry.consumeNextPacket());     // PKT_B
        System.out.println("Consumed:     " + telemetry.consumeNextPacket());     // null
    }
}

