import java.util.Queue;

public class BatchProcessor {
    public static int processBatch(Queue<Integer> queue, int batchSize) {
        if (queue == null || batchSize <= 0) return 0;
        int sum = 0;
        int count = 0;
        while (!queue.isEmpty() && count < batchSize) {
            Integer item = queue.poll();
            if (item != null) {
                sum += item;
                count++;
            }
        }
        return sum;
    }
}

