import java.util.Queue;

public class QueueCounter {
    public static int countEven(Queue<Integer> queue) {
        if (queue == null || queue.isEmpty()) return 0;
        int evens = 0;
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            Integer item = queue.poll();
            if (item != null && item % 2 == 0) {
                evens++;
            }
            queue.offer(item); // Cycle back to tail to restore order
        }
        return evens;
    }
}
